insert into public.lessons select * from jsonb_populate_recordset(null::public.lessons, $seed$[{"id":"week-1","week":1,"title":"English Assessment","skill":"Grammar","duration":45,"description":"A little discovery before the journey. Find your strengths and set your learning goals.","objectives":["Check your grammar and vocabulary","Read a short passage","Write about yourself","Set a personal learning goal"],"activities":"Start with the mixed grammar quiz. Try a reading activity, then write a short introduction. Discuss what felt easy and what you want to improve with your tutor.","homework":"Write 80–100 words introducing yourself, your hobbies, and one thing you want to achieve in English."},{"id":"week-2","week":2,"title":"Verb Tenses","skill":"Grammar","duration":40,"description":"Present, past, and future. Learn to choose the right tense for your story.","objectives":["Present simple and continuous","Past simple and irregular verbs","Present perfect","Future plans and predictions"],"activities":"Compare “I play football” with “I am playing football.” Use the past simple for finished times and the present perfect for experiences. Practise each tense in the grammar quiz.","homework":"Write five sentences about yesterday, five about your routine, and three about your future plans."},{"id":"week-3","week":3,"title":"Sentence Structure and Grammar","skill":"Grammar","duration":35,"description":"Word order, questions, negatives, articles, prepositions, and subject–verb agreement.","objectives":["Learn the main grammar rules","Do practice exercises","Write your own sentences","Get feedback and set homework"],"activities":"English sentences usually follow subject + verb + object: “Lena reads a book.” Questions often begin with an auxiliary: “Does Lena read?” Use “a” before a consonant sound, “an” before a vowel sound, and “the” for something specific.","homework":"Write eight sentences about your school day. Include two questions, two negatives, and the articles a, an, and the."},{"id":"week-4","week":4,"title":"Vocabulary and Reading Comprehension","skill":"Vocabulary","duration":40,"description":"Context clues, synonyms, antonyms, phrasal verbs, and short texts.","objectives":["Use context to discover meaning","Learn synonyms and antonyms","Practise phrasal verbs","Summarize a short passage"],"activities":"Read the whole sentence before looking up a word. Contrast words such as “but” can reveal an opposite meaning. “Give up” means stop trying; “look after” means take care of. Review the flashcards, then read The Repair Café.","homework":"Learn six new words and use each one in a sentence. Summarize one reading passage in three sentences."},{"id":"week-5","week":5,"title":"Writing Better Paragraphs and Essays","skill":"Writing","duration":45,"description":"Topic sentences, supporting details, transitions, punctuation, and clear conclusions.","objectives":["Write a clear topic sentence","Support ideas with examples","Connect ideas with transitions","Finish with a strong conclusion"],"activities":"Begin a paragraph with one clear idea. Add reasons and examples. Use “however” to contrast and “therefore” for a result. Your conclusion should return to your main idea. Open the Writing Workshop and practise with a school-related opinion.","homework":"Write 120–150 words explaining whether students should have less homework. Include an example and a conclusion."},{"id":"week-6","week":6,"title":"Reading and Literature","skill":"Reading","duration":40,"description":"Main ideas, inference, character, theme, and evidence from the text.","objectives":["Identify the main idea","Make an inference using evidence","Explore character and theme","Explain the author’s purpose"],"activities":"A detail tells you something specific; a main idea connects the details. An inference combines clues with your knowledge. Use a quotation or a precise detail to support an answer. Read The Last Seat and explain how its character changes.","homework":"Complete a reading activity. Write one inference and explain which detail supports it."},{"id":"week-7","week":7,"title":"Speaking and Listening","skill":"Speaking","duration":45,"description":"Everyday conversations, pronunciation, listening, and expressing your opinions.","objectives":["Retell a short story","Practise pronunciation","Listen for important details","Express an opinion politely"],"activities":"Use the vocabulary pronunciation buttons to listen and repeat. Read a passage aloud, then retell it without looking. During your tutor session, explain your opinion using “I think… because…” and ask a follow-up question.","homework":"Prepare a one-minute talk about a hobby. Note three questions to ask your tutor. Speaking is assessed by your tutor during the session."},{"id":"week-8","week":8,"title":"Review and Test Preparation","skill":"Grammar","duration":50,"description":"Mixed practice, weak areas, a writing assessment, and your final progress report.","objectives":["Review challenging grammar","Revisit difficult vocabulary","Complete a reading test","Reflect on your progress"],"activities":"Check the Progress page for topics below 70% accuracy. Retry those quizzes, review words marked Needs Practice, and complete one reading and one writing activity. Compare your results with your first attempts.","homework":"Write a reflection: What has improved? What will you practise next? Discuss your progress report with your tutor."}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.quiz_questions select * from jsonb_populate_recordset(null::public.quiz_questions, $seed$[{"id":"q1","lesson_id":"week-2","topic":"Present simple","difficulty":"Beginner","type":"choice","prompt":"She ___ to school every day.","options":["go","goes","going","gone"],"answer":"goes","explanation":"With he, she, or it, add -s to the verb in the present simple."},{"id":"q2","lesson_id":"week-2","topic":"Present continuous","difficulty":"Intermediate","type":"choice","prompt":"Look! The students ___ a science experiment.","options":["do","did","are doing","have done"],"answer":"are doing","explanation":"Use am/is/are + -ing for something happening right now."},{"id":"q3","lesson_id":"week-2","topic":"Past simple","difficulty":"Beginner","type":"blank","prompt":"Yesterday, we ___ (go) to the library.","options":[],"answer":"went","explanation":"“Yesterday” is a finished past time. The past form of go is went."},{"id":"q4","lesson_id":"week-2","topic":"Present perfect","difficulty":"Intermediate","type":"choice","prompt":"I ___ this book three times so far.","options":["read yesterday","have read","am reading","will read"],"answer":"have read","explanation":"“So far” connects past experiences with the present. Use have + past participle."},{"id":"q5","lesson_id":"week-2","topic":"Future forms","difficulty":"Intermediate","type":"choice","prompt":"Look at those dark clouds! It ___ rain.","options":["is going to","has","was","does"],"answer":"is going to","explanation":"Use going to for predictions based on evidence you can see now."},{"id":"q6","lesson_id":"week-2","topic":"Present perfect","difficulty":"Intermediate","type":"boolean","prompt":"“I have visited Berlin last year” is grammatically correct.","options":["True","False"],"answer":"False","explanation":"“Last year” is a finished time. Say “I visited Berlin last year.”"},{"id":"q7","lesson_id":"week-3","topic":"Word order","difficulty":"Intermediate","type":"correction","prompt":"Correct this sentence: “Always I do my homework after school.”","options":[],"answer":"I always do my homework after school.","explanation":"Adverbs of frequency usually go before the main verb: I always do…"},{"id":"q8","lesson_id":"week-3","topic":"Articles","difficulty":"Beginner","type":"choice","prompt":"Lena wants to become ___ engineer.","options":["a","an","the","no article"],"answer":"an","explanation":"Use an before a vowel sound. “Engineer” begins with a vowel sound."},{"id":"q9","lesson_id":"week-3","topic":"Questions and negatives","difficulty":"Intermediate","type":"choice","prompt":"Which question is correct?","options":["Does he likes music?","Do he like music?","Does he like music?","He does like music?"],"answer":"Does he like music?","explanation":"After does, use the base form of the verb: like, not likes."},{"id":"q10","lesson_id":"week-3","topic":"Prepositions","difficulty":"Beginner","type":"blank","prompt":"The lesson starts ___ 4 o’clock.","options":[],"answer":"at","explanation":"Use at for a specific clock time, on for days, and in for months."},{"id":"q11","lesson_id":"week-3","topic":"Subject–verb agreement","difficulty":"Intermediate","type":"choice","prompt":"Each of the students ___ a notebook.","options":["have","has","having","are having"],"answer":"has","explanation":"Each refers to one individual, so it takes a singular verb: has."},{"id":"q12","lesson_id":"week-3","topic":"Articles","difficulty":"Intermediate","type":"boolean","prompt":"“She is a university student” uses the correct article.","options":["True","False"],"answer":"True","explanation":"University starts with a /y/ consonant sound, so use a, not an."},{"id":"q13","lesson_id":"week-4","topic":"Phrasal verbs","difficulty":"Intermediate","type":"choice","prompt":"“Don’t give up!” means…","options":["Don’t arrive late","Don’t stop trying","Don’t look outside","Don’t give a present"],"answer":"Don’t stop trying","explanation":"Give up means stop trying or stop doing something."},{"id":"q14","lesson_id":"week-2","topic":"Past simple","difficulty":"Intermediate","type":"correction","prompt":"Correct this sentence: “She didn’t went to the cinema.”","options":[],"answer":"She didn’t go to the cinema.","explanation":"After didn’t, use the base form go. The auxiliary already shows the past."},{"id":"q15","lesson_id":"week-3","topic":"Prepositions","difficulty":"Intermediate","type":"choice","prompt":"I have lived in Hamburg ___ 2022.","options":["for","since","during","at"],"answer":"since","explanation":"Since marks a starting point. For describes a length of time."},{"id":"q16","lesson_id":"week-5","topic":"Linking words","difficulty":"Intermediate","type":"choice","prompt":"The task was difficult. ___, I finished it.","options":["Because","However","For example","Therefore"],"answer":"However","explanation":"However introduces a contrast between difficulty and success."}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.vocabulary select * from jsonb_populate_recordset(null::public.vocabulary, $seed$[{"id":"v1","word":"achieve","translation":"erreichen","definition":"To successfully reach a goal through effort.","example":"You can achieve your goals with a little practice every day.","theme":"Academic","difficulty":"B1"},{"id":"v2","word":"assignment","translation":"die Aufgabe","definition":"A piece of work that a teacher asks you to complete.","example":"Our English assignment is due on Friday.","theme":"School","difficulty":"B1"},{"id":"v3","word":"curious","translation":"neugierig","definition":"Wanting to learn or know more about something.","example":"Mia was curious about how the old clock worked.","theme":"Emotions","difficulty":"B1"},{"id":"v4","word":"improve","translation":"verbessern","definition":"To become better or make something better.","example":"Reading a little each day can improve your vocabulary.","theme":"School","difficulty":"A2"},{"id":"v5","word":"look after","translation":"sich kümmern um","definition":"To take care of a person, animal, or thing.","example":"I look after my neighbour’s cat during the holidays.","theme":"Everyday life","difficulty":"B1"},{"id":"v6","word":"journey","translation":"die Reise","definition":"An act of travelling from one place to another.","example":"The train journey from Berlin to Munich took four hours.","theme":"Travel","difficulty":"A2"},{"id":"v7","word":"confident","translation":"selbstbewusst","definition":"Feeling sure about your abilities.","example":"After practising, Ben felt confident about his presentation.","theme":"Emotions","difficulty":"B1"},{"id":"v8","word":"evidence","translation":"der Beleg","definition":"Facts or details that support an idea.","example":"Use evidence from the text to explain your answer.","theme":"Academic","difficulty":"B1"},{"id":"v9","word":"give up","translation":"aufgeben","definition":"To stop trying to do something.","example":"The puzzle was hard, but we didn’t give up.","theme":"Everyday life","difficulty":"B1"},{"id":"v10","word":"explore","translation":"erkunden","definition":"To travel around a place or investigate an idea.","example":"We explored the forest and found a small lake.","theme":"Travel","difficulty":"B1"},{"id":"v11","word":"challenge","translation":"die Herausforderung","definition":"Something difficult that tests your skills.","example":"Learning a new song on the guitar was a fun challenge.","theme":"Hobbies","difficulty":"B1"},{"id":"v12","word":"however","translation":"jedoch","definition":"A word used to introduce a contrasting idea.","example":"It was raining. However, we still went for a walk.","theme":"Academic","difficulty":"B1"}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.reading_passages select * from jsonb_populate_recordset(null::public.reading_passages, $seed$[{"id":"r1","title":"The Repair Café","level":"B1 · Everyday life","body":"On the first Saturday of each month, a small café in Hamburg becomes something unusual. Instead of serving only coffee and cake, it welcomes people carrying broken things: lamps, bicycles, and even old radios.\n\nFourteen-year-old Jonas first visited with a broken desk lamp. He expected someone to fix it for him, but a volunteer named Eva handed him a screwdriver. “I’ll help you,” she said, “but you’re going to do the repairing.” Together, they discovered a loose wire. Ten minutes later, the lamp worked again.\n\nJonas returned the following month, this time to help someone else. He couldn’t repair everything, but he could ask questions and learn. The café’s goal isn’t simply to save objects from the rubbish bin. It is also to bring neighbours together and remind them that learning has no age limit.\n\n“Buying something new is easy,” Jonas says. “Understanding how something works is much more satisfying.”"},{"id":"r2","title":"The Last Seat","level":"B1 · A short story","body":"Mila stood at the classroom door, searching for an empty seat. It was her first day at a new school, and every table seemed to belong to a group of friends. There was one free chair beside a boy who was drawing in a notebook.\n\n“Is this seat taken?” she asked. He shook his head without looking up. Mila sat down and opened her book. For the next ten minutes, neither of them spoke. Then she noticed his drawing: a tiny city built on the back of a giant turtle.\n\n“That’s incredible,” she said. The boy looked surprised. “You think so? I’m making a comic, but I can’t think of a story.” Mila paused. She had spent the whole morning wishing she could disappear. Now she had an idea. “What if the turtle gets lost?”\n\nBy lunchtime, the notebook held two new pages of adventures. Mila still didn’t know most of her classmates’ names. But the last empty seat no longer felt like the wrong place to be."}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.reading_questions select * from jsonb_populate_recordset(null::public.reading_questions, $seed$[{"id":"r1q1","prompt":"What is the main purpose of the passage?","options":["To advertise a new lamp","To explain how a repair café helps objects and people","To compare different cafés","To teach electrical engineering"],"answer":"To explain how a repair café helps objects and people","explanation":"The text describes both repairing objects and bringing neighbours together.","passage_id":"r1"},{"id":"r1q2","prompt":"Why did Eva give Jonas a screwdriver?","options":["She wanted him to leave","She had already repaired the lamp","She wanted him to learn by repairing it himself","She was selling tools"],"answer":"She wanted him to learn by repairing it himself","explanation":"Eva says she will help, but Jonas will do the repairing.","passage_id":"r1"},{"id":"r1q3","prompt":"How did Jonas’s role change on his second visit?","options":[],"answer":"He returned to help someone else.","explanation":"At first he needed help. On his second visit he became a helper. Your tutor can discuss other ways to express this answer.","passage_id":"r1"},{"id":"r1q4","prompt":"What can we infer about Jonas?","options":["He has become more curious and willing to help","He dislikes learning new skills","He plans to buy a café","He can fix every object"],"answer":"He has become more curious and willing to help","explanation":"He returns to help and describes understanding things as satisfying.","passage_id":"r1"},{"id":"r2q1","prompt":"How does Mila feel at the beginning?","options":["Nervous and unsure","Angry at the teacher","Excited to draw","Confident and popular"],"answer":"Nervous and unsure","explanation":"She searches for a seat and wishes she could disappear.","passage_id":"r2"},{"id":"r2q2","prompt":"What starts the conversation?","options":["A homework question","Mila’s comment about the drawing","The teacher’s instructions","An argument about a chair"],"answer":"Mila’s comment about the drawing","explanation":"Mila says “That’s incredible” after seeing the turtle city.","passage_id":"r2"},{"id":"r2q3","prompt":"Which theme best fits this story?","options":["Small shared interests can begin a friendship","It is best to avoid strangers","School rules should change","Art is more important than reading"],"answer":"Small shared interests can begin a friendship","explanation":"Their interest in the comic turns an uncomfortable silence into a connection.","passage_id":"r2"}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.writing_assignments select * from jsonb_populate_recordset(null::public.writing_assignments, $seed$[{"id":"w1","title":"Should students have less homework?","format":"Opinion paragraph","min_words":120,"instructions":"Write 120–150 words explaining your opinion. Start with a clear topic sentence, give two reasons and one example, use a linking word, and finish with a conclusion."},{"id":"w2","title":"A small moment, a big difference","format":"Short story","min_words":100,"instructions":"Write 100–180 words about someone who helps another person. Describe the setting, include a short conversation, and explain what changes. Use the past simple."},{"id":"w3","title":"A little introduction","format":"Personal introduction","min_words":80,"instructions":"Write 80–100 words about yourself, your school, and your hobbies. Include one English learning goal and explain why it matters to you."}]$seed$::jsonb) on conflict (id) do nothing;
